html:
{% set ws = frappe.db.get_value("Institution Settings") or {} %}
{% set pc = None %}
{% if frappe.db.exists("Applicant Portal Config", "Applicant Portal Config") %}
{% set pc = frappe.get_doc("Applicant Portal Config", "Applicant Portal Config") %}
{% endif %}
{% set pace_app = None %}
{% if doc.pace_application and frappe.db.exists("PACE Application", doc.pace_application) %}
{% set pace_app = frappe.get_doc("PACE Application", doc.pace_application) %}
{% endif %}
{% set prog_title = frappe.db.get_value("PACE Programme", doc.program, "programme_name") if doc.program else "" %}
{% set pr_gateway = frappe.db.get_value("Payment Request", doc.payment_request, "payment_gateway") if doc.payment_request else "" %}

{# DYNAMIC CAMPUS RESOLUTION #}
{% set campus = None %}
{% if doc.campus %}
    {% set campus = frappe.get_doc("Campus", doc.campus) if frappe.db.exists("Campus", doc.campus) else None %}
{% endif %}
{% if not campus %}
    {% set campus_list = frappe.get_all("Campus", filters={"is_active": 1}, limit=1) %}
    {% if campus_list %}
        {% set campus = frappe.get_doc("Campus", campus_list[0].name) %}
    {% endif %}
{% endif %}

{# CAMPUS LOGO AND DETAILS #}
{% set logo_src = campus.logo if campus and campus.logo else "" %}
{% set inst_name = campus.campus_name if campus else ((pc.portal_title if pc else None) or ws.get("title") or _("Institution")) %}
{% set inst_addr = "" %}
{% if campus %}
    {% set inst_addr = (campus.address or "") + (", " + campus.city if campus.city else "") + (", " + campus.state if campus.state else "") %}
{% endif %}
{% if not inst_addr and pc %}
    {% set inst_addr = pc.footer_address or "" %}
{% endif %}
{% set inst_phone = campus.phone_number if campus else ((pc.footer_phone if pc else None) or "") %}

{% set pay_date_str = frappe.utils.format_datetime(doc.payment_date, "dd/MM/yyyy") if doc.payment_date else "" %}
{% set gen_date_str = frappe.utils.format_datetime(doc.generated_on, "dd/MM/yyyy HH:mm") if doc.generated_on else "" %}

<style>
    @import url('https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;0,900;1,300;1,400;1,700;1,900&display=swap');

    @media print {
        @page { size: A4; margin: 10mm 12mm; }
        body { margin: 0; padding: 0; background: #fff; }
    }

    * {
        font-family: 'Merriweather', Georgia, 'Times New Roman', serif;
        color: #000;
        box-sizing: border-box;
    }

    body {
        background: #fff;
        padding: 0;
        margin: 0;
    }

    .receipt-wrap {
        width: 100%;
        max-width: 700px;
        margin: 0 auto;
        padding: 20px;
        background: #fff;
    }

    .page-title {
        text-align: center;
        font-size: 16px;
        font-weight: 700;
        margin: 0 0 12px;
    }

    .outer-table {
        width: 100%;
        border-collapse: collapse;
        border: 1.5px solid #333;
    }

    .outer-table > tbody > tr > td {
        padding: 0;
        border-bottom: 1.5px solid #333;
    }

    .outer-table > tbody > tr:last-child > td {
        border-bottom: none;
    }

    .header-cell {
        text-align: center;
        padding: 18px 20px 14px;
    }

    .header-cell img.inst-logo {
        display: block;
        margin: 0 auto 10px;
        width: 80px;
        height: 80px;
        object-fit: contain;
    }

    .logo-placeholder {
        width: 72px;
        height: 72px;
        border: 2px solid #8b1a1a;
        border-radius: 4px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 10px;
        font-size: 30px;
        color: #8b1a1a;
    }

    .inst-name {
        font-size: 17px;
        font-weight: 700;
        margin-bottom: 5px;
    }

    .inst-addr {
        font-size: 12px;
        line-height: 1.6;
        font-weight: 700;
    }

    .inst-phone {
        font-size: 13px;
        font-weight: 700;
        margin-top: 3px;
    }

    .info-cell {
        padding: 7px 20px;
        font-size: 13px;
        text-align: center;
    }

    .amount-confirm-cell {
        padding: 10px 30px;
        font-size: 13px;
        text-align: center;
        line-height: 1.8;
    }

    .detail-table {
        width: 100%;
        border-collapse: collapse;
    }

    .detail-table tr {
        border-bottom: 1px solid #ccc;
    }

    .detail-table tr:last-child {
        border-bottom: none;
    }

    .detail-table td.lbl {
        width: 190px;
        padding: 7px 14px 7px 20px;
        font-size: 13px;
        vertical-align: middle;
    }

    .detail-table td.val {
        padding: 7px 16px;
        font-size: 13px;
        font-weight: 700;
        vertical-align: middle;
    }

    .product-table {
        width: 100%;
        border-collapse: collapse;
    }

    .product-table th {
        padding: 8px 10px;
        font-size: 13px;
        font-weight: 700;
        text-align: center;
        border-right: 1px solid #ccc;
        border-bottom: 1px solid #ccc;
    }

    .product-table th:last-child { border-right: none; }

    .product-table td {
        padding: 7px 10px;
        font-size: 13px;
        vertical-align: middle;
        border-right: 1px solid #ccc;
        border-bottom: 1px solid #ccc;
    }

    .product-table td:last-child { border-right: none; }
    .product-table tr:last-child td { border-bottom: none; }

    .product-table tr.total-row td {
        font-weight: 700;
    }

    .tc { text-align: center; }
    .tr { text-align: right; }

    .words-cell {
        padding: 8px 20px;
        font-size: 13px;
        font-weight: 700;
    }

    .nonref-cell {
        padding: 9px 20px;
        font-size: 13px;
        font-weight: 700;
        text-align: center;
    }

    .tick { color: #1a7a1a; font-size: 15px; }

    .footer-cell {
        padding: 9px 20px;
        font-size: 12px;
        text-align: center;
        line-height: 1.7;
    }

    .footer-cell .sys-note { font-style: italic; }
    .footer-cell .disc { font-weight: 700; }
</style>

<div class="receipt-wrap">
    <p class="page-title">Electronic Receipt</p>

    <table class="outer-table">
      <tbody>

        <tr>
          <td class="header-cell">
            {% if logo_src %}
              <img class="inst-logo" src="{{ logo_src }}" alt="Logo">
            {% else %}
              <div class="logo-placeholder">⚖</div>
            {% endif %}
            <div class="inst-name">{{ inst_name }}</div>
            {% if inst_addr %}
              <div class="inst-addr">{{ inst_addr }}</div>
            {% endif %}
            {% if inst_phone %}
              <div class="inst-phone">{{ _("Phone") }} : {{ inst_phone }}</div>
            {% endif %}
          </td>
        </tr>

        <tr>
          <td class="info-cell">
            {{ _("Application Number") }}: <strong>{{ doc.pace_application or doc.name }}</strong>
          </td>
        </tr>

        <tr>
          <td class="info-cell">
            {{ _("To") }}: <strong>{{ doc.applicant_name or "" }}</strong>
          </td>
        </tr>

        <tr>
          <td class="amount-confirm-cell">
            {{ _("Amount submission of INR") }} <strong>{{ "%.2f"|format(doc.amount) }}</strong> {{ _("is successful.") }}<br>
            {{ _("Amount received for Program") }} &#8211; <strong>{{ prog_title or doc.program or "" }}</strong>
          </td>
        </tr>

        <tr>
          <td style="padding:0;">
            <table class="detail-table">
              <tr>
                <td class="lbl">{{ _("Date of Receipt") }}</td>
                <td class="val">{{ pay_date_str }}</td>
              </tr>
              <tr>
                <td class="lbl">{{ _("Payment Type") }}</td>
                <td class="val">{{ pr_gateway or _("Online") }}</td>
              </tr>
              <tr>
                <td class="lbl">{{ _("Transaction Mode") }}</td>
                <td class="val">{{ _("Online") }}</td>
              </tr>
              {% if doc.transaction_id %}
              <tr>
                <td class="lbl">{{ _("Transaction ID") }}</td>
                <td class="val">{{ doc.transaction_id }}</td>
              </tr>
              {% endif %}
              {% if pace_app and pace_app.academic_year %}
              <tr>
                <td class="lbl">{{ _("Academic Year") }}</td>
                <td class="val">{{ pace_app.academic_year }}</td>
              </tr>
              {% endif %}
              {% if doc.currency %}
              <tr>
                <td class="lbl">{{ _("Currency") }}</td>
                <td class="val">{{ doc.currency }}</td>
              </tr>
              {% endif %}
              {% if gen_date_str %}
              <tr>
                <td class="lbl">{{ _("Receipt Generated On") }}</td>
                <td class="val">{{ gen_date_str }}</td>
              </tr>
              {% endif %}
            </table>
          </td>
        </tr>

        <tr>
          <td style="padding:0;">
            <table class="product-table">
              <thead>
                <tr>
                  <th style="width:55px;">{{ _("S.No.") }}</th>
                  <th>{{ _("Product") }}</th>
                  <th style="width:85px;">{{ _("Quantity") }}</th>
                  <th style="width:110px;">{{ _("Price") }}</th>
                  <th style="width:110px;">{{ _("Amount") }}</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td class="tc">1</td>
                  <td>{{ doc.fee_type or _("Admission Fee") }}</td>
                  <td class="tc">1</td>
                  <td class="tr">{{ "%.2f"|format(doc.amount) }}</td>
                  <td class="tr">{{ "%.2f"|format(doc.amount) }}</td>
                </tr>
                <tr class="total-row">
                  <td colspan="3" class="tr">{{ _("Total") }}</td>
                  <td class="tr">{{ "%.2f"|format(doc.amount) }}</td>
                  <td class="tr">{{ "%.2f"|format(doc.amount) }}</td>
                </tr>
              </tbody>
            </table>
          </td>
        </tr>

        <tr>
          <td class="words-cell">
            {{ frappe.utils.money_in_words(doc.amount, doc.currency or "INR") }}
          </td>
        </tr>

        <tr>
          <td class="nonref-cell">
            <span class="tick">&#10003;</span>&nbsp; {{ _("I accept that fee paid is non-refundable.") }}
          </td>
        </tr>

        <tr>
          <td class="footer-cell">
            <div class="sys-note">{{ _("This is a system-generated receipt and does not require a signature.") }}</div>
            <div class="disc"><strong>{{ _("Disclaimer:") }}</strong> {{ _("The total charges include 18% GST") }}</div>
          </td>
        </tr>

      </tbody>
    </table>
</div>
